"""Small guarded episode patch. Journal prose is an episode draft, RU + UK."""
import json,copy,sys
from pathlib import Path
ART='assets/stories/Evan/inspections/finale/'
def page(title,titleUk,text,textUk,image=None):
 p=dict(title=title,titleUk=titleUk,text=text,textUk=textUk)
 if image:p['image']=image
 return p
PAGES=[
page('01 · С чего я начал','01 · З чого я почав',
'Тележка должна менять путь, если переставить штырьки на барабане. Не разбирать её каждый раз, а менять порядок движений. Старые рисунки оставляю: иначе потом решу, что всё сразу понимал.\n\nВ папке было три команды: вперёд, поворот, стой. На бумаге они послушные. Но рисунок не объясняет, откуда берётся усилие и что произойдёт, если колесо упрётся в камень.\n\nГлавный вопрос: барабан задаёт порядок, но сам по себе ничего не приводит в движение. Не путать управление с источником силы.',
'Візок має змінювати шлях, якщо переставити кілочки на барабані. Не розбирати його щоразу, а змінювати порядок рухів. Старі малюнки залишаю: інакше потім вирішу, що все відразу розумів.\n\nУ теці було три команди: уперед, поворот, стій. На папері вони слухняні. Але малюнок не пояснює, звідки береться зусилля і що станеться, якщо колесо впирається в камінь.\n\nГоловне питання: барабан задає порядок, але сам собою нічого не приводить у рух. Не плутати керування з джерелом сили.',
'assets/stories/Evan/inspections/draft-folder-v1.png'),
page('02 · После разговора у станка','02 · Після розмови біля верстата',
'Я всё время представлял колёса. Преподаватель показал другую последовательность: подать заготовку, закрепить, опустить сверло. Если поменять местами последние действия, заготовку вырвет.\n\nЗначит, можно сначала обойтись без тележки. Собрать барабан и два рычага. Один поднимается, другой ждёт. Потом наоборот. Важно не то, насколько большая получилась вещь, а повторяет ли она нужное движение.\n\nДля первого образца — только ручка. Крутить медленно самому. Не подключать ни колесо, ни груз, пока не вижу, где всё заедает.\n\nЗаписать не только удачный вариант. Ошибки тоже взять с собой, когда снова пойду к преподавателю.',
'Я весь час уявляв колеса. Викладач показав іншу послідовність: подати заготовку, закріпити, опустити свердло. Якщо поміняти місцями останні дії, заготовку вирве.\n\nОтже, можна спершу обійтися без візка. Зібрати барабан і два важелі. Один підіймається, другий чекає. Потім навпаки. Важливо не те, яка велика вийшла річ, а чи повторює вона потрібний рух.\n\nДля першого зразка — лише ручка. Крутити повільно самому. Не під’єднувати ні колесо, ні вантаж, поки не бачу, де все заїдає.\n\nЗаписати не лише вдалий варіант. Помилки теж узяти із собою, коли знову піду до викладача.'),
page('03 · Разметка барабана','03 · Розмітка барабана',
'Пробная разметка: разделить окружность на двенадцать равных частей.\n\n360° ÷ 12 = 30° между отметками.\n\nЕсли вручную сделать один оборот за двенадцать счётов, на один промежуток придётся один счёт. Это только удобство проверки: рука не держит точную скорость.\n\nПервый ряд штырьков касается рычага А, второй — рычага Б. Поставить отметку начала оборота, чтобы не начинать каждый раз с другого места.\n\nПопробовать сначала большой промежуток между срабатываниями. Не ставить штырьки теснее ради красивого рисунка. Рычаг должен успеть вернуться. Время возврата ещё измерить.',
'Пробна розмітка: поділити коло на дванадцять рівних частин.\n\n360° ÷ 12 = 30° між позначками.\n\nЯкщо вручну зробити один оберт за дванадцять відліків, на один проміжок припаде один відлік. Це лише зручність перевірки: рука не тримає точної швидкості.\n\nПерший ряд кілочків торкається важеля А, другий — важеля Б. Поставити позначку початку оберту, щоб не починати щоразу з іншого місця.\n\nСпробувати спочатку великий проміжок між спрацьовуваннями. Не ставити кілочки щільніше заради гарного малюнка. Важіль має встигнути повернутися. Час повернення ще виміряти.'),
page('04 · Усилие и остановка','04 · Зусилля й зупинка',
'На отдельном рисунке: от опоры до одного конца рычага две меры, до другого — одна. В идеальном случае длинное плечо позволяет поднимать вдвое больший груз на коротком. Но оно проходит вдвое больший путь. Ничего не появляется даром.\n\nДля проверки: 1 груз × 2 меры = 2 груза × 1 мера. Без учёта трения и веса самого рычага. На дереве результат будет хуже.\n\nНе пытаться исправить заедание более сильным вращением. Сначала остановить ручку и посмотреть на след касания.\n\nВопрос преподавателю: как прервать передачу движения, если привод уже не рука? Свободный ход? Выводимая из зацепления деталь? Пока не решил.',
'На окремому малюнку: від опори до одного кінця важеля дві міри, до іншого — одна. В ідеальному випадку довге плече дозволяє підіймати вдвічі більший вантаж на короткому. Але воно проходить удвічі більший шлях. Нічого не з’являється задарма.\n\nДля перевірки: 1 вантаж × 2 міри = 2 вантажі × 1 міра. Без урахування тертя й ваги самого важеля. На дереві результат буде гіршим.\n\nНе намагатися виправити заїдання сильнішим обертанням. Спершу зупинити ручку й подивитися на слід дотику.\n\nПитання викладачеві: як перервати передачу руху, якщо приводом уже буде не рука? Вільний хід? Деталь, яку можна вивести із зачеплення? Поки не вирішив.'),
page('05 · Что пришлось переделать','05 · Що довелося переробити',
'Первая сборка. Барабан крутился отдельно, но после установки второго рычага ручка стала идти тяжелее. Сначала решил, что виноваты штырьки. Проверил по одному рычагу: один всё равно цеплял боком.\n\nПередвинул опору. Стало свободнее. Запомнить: если ошибка появилась после новой детали, это ещё не значит, что виновата именно она.\n\nОдин штырёк вылезал из отверстия. Не стал сразу заливать всё клеем: тогда уже не переставишь. Подогнал другой, старый оставил рядом для сравнения.\n\nДесять медленных оборотов без груза — только первая проба. Это не доказательство надёжности. Проверить после перерыва, потом с небольшой нагрузкой. Записать отдельно, где ручку приходится подталкивать.',
'Перше складання. Барабан крутився окремо, але після встановлення другого важеля ручка стала йти важче. Спершу вирішив, що винні кілочки. Перевірив по одному важелю: один усе одно чіплявся боком.\n\nПересунув опору. Стало вільніше. Запам’ятати: якщо помилка з’явилася після нової деталі, це ще не означає, що винна саме вона.\n\nОдин кілочок вилазив з отвору. Не став одразу заливати все клеєм: тоді вже не переставиш. Підігнав інший, старий залишив поруч для порівняння.\n\nДесять повільних обертів без вантажу — лише перша проба. Це не доказ надійності. Перевірити після перерви, потім із невеликим навантаженням. Записати окремо, де ручку доводиться підштовхувати.'),
page('06 · Что я хочу спросить','06 · Що я хочу запитати',
'Как сделать, чтобы рычаг возвращался уверенно, но не бил по барабану? Как проверить износ отверстий, если штырьки часто переставлять? Какая часть должна уступить первой при заклинивании, чтобы не сломалось всё остальное?\n\nОтдельно: нельзя выдавать одинаковое число оборотов за одинаковую работу. Пока нет нагрузки, я проверяю только порядок движений.\n\nВзять на следующую встречу: старые рисунки тележки, этот журнал, образец и неудачный штырёк. Показать, что изменил, а не только то, что получилось.\n\nНе забыть спросить про зажим той студентки. Три месяца на одну деталь. Теперь это уже не кажется странным.\n\nЯ ещё не знаю, как сделать целый станок. Но уже знаю, что хочу проверить завтра.',
'Як зробити, щоб важіль повертався впевнено, але не бив по барабану? Як перевірити зношування отворів, якщо кілочки часто переставляти? Яка частина має поступитися першою під час заклинювання, щоб не зламалося все інше?\n\nОкремо: не можна видавати однакову кількість обертів за однакову роботу. Поки немає навантаження, я перевіряю лише порядок рухів.\n\nУзяти на наступну зустріч: старі малюнки візка, цей журнал, зразок і невдалий кілочок. Показати, що змінив, а не тільки те, що вдалося.\n\nНе забути спитати про затискач тієї студентки. Три місяці на одну деталь. Тепер це вже не здається дивним.\n\nЯ ще не знаю, як зробити цілий верстат. Але вже знаю, що хочу перевірити завтра.')]
def journal(count):return dict(title='Рабочий журнал Евана',titleUk='Робочий журнал Евана',x=22,y=48,width=28,height=27,pages=copy.deepcopy(PAGES[:count]))
def patch(envelope):
 out=copy.deepcopy(envelope);e=out['episode'];nodes={n['id']:n for n in e['nodes']}
 required=['evan-finale-thoughts','evan-finale-results']
 assert all(id in nodes for id in required),'wrong episode revision'
 if 'evan-finale-journal' not in nodes:
  n=dict(id='evan-finale-journal',kind='dialogue',title='Мой рабочий журнал',titleUk='Мій робочий журнал',editorSceneId='scene-evan-evening-room',x=8600,y=3100,speaker='',showPortrait=False,firstShowPortrait=False,text='Здесь сохраню рисунки и вопросы. Журнал на столе можно открыть.',textUk='Тут збережу малюнки й питання. Журнал на столі можна відкрити.',image=ART+'engineering-journal-evening-v1.png',imageFit='contain',imageMotion={'type':'none'},journal=journal(4),slides=[],links=[dict(id='evan-journal-back',to='evan-finale-thoughts',label='Вернуться к своим мыслям',labelUk='Повернутися до своїх думок')]);e['nodes'].append(n)
  nodes['evan-finale-thoughts']['links'].insert(0,dict(id='evan-journal-read',to=n['id'],label='Открыть рабочий журнал',labelUk='Відкрити робочий журнал'))
 n=nodes['evan-finale-results'];n.update(image=ART+'engineering-journal-desk-v1.png',imageFit='contain',imageMotion={'type':'none'},journal=journal(6))
 # Show the desk only on the narrator's opening page; parents then speak in the room.
 if n.get('slides'):n['slides'][0].update(image='',journal=None)
 # Inheritance is from the node, not the previous slide: clear each later page.
 for s in n.get('slides',[]):s.update(image='',journal=None)
 return out
if __name__=='__main__':
 src,dst=map(Path,sys.argv[1:]);out=patch(json.loads(src.read_text()));dst.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(dst)
